# Fix the propagation direction
def solve(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find source row(s) containing non-zeros
    source_row = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                source_row = r
                break
        if source_row is not None:
            break

    if source_row is None:
        return [[0]*cols for _ in range(rows)]

    # Start with all zeros
    output = [[0]*cols for _ in range(rows)]

    # Preserve source row
    for c in range(cols):
        output[source_row][c] = grid[source_row][c]

    # For each non-zero value in source row, propagate upward (decreasing row index)
    for c in range(cols):
        val = grid[source_row][c]
        if val == 0:
            continue

        # Propagate upward (to lower row indices)
        for dr in range(1, source_row + 1):
            r = source_row - dr
            if r < 0:
                break
            # Closest cell (dr=1) keeps original value
            if dr == 1:
                output[r][c] = val
            else:
                output[r][c] = 1

    return output

