def solve(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    source_row = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                source_row = r
                break
        if source_row is not None:
            break

    if source_row is None:
        return [[0]*cols for _ in range(rows)]

    output = [[0]*cols for _ in range(rows)]
    for c in range(cols):
        output[source_row][c] = grid[source_row][c]

    propagation_dist = {2: 4, 8: 3}

    for c in range(cols):
        val = grid[source_row][c]
        if val in propagation_dist:
            dist = propagation_dist[val]
            stop_row = source_row - dist

            for r in range(stop_row + 1, source_row):
                if r >= 0:
                    output[r][c] = 1

            if stop_row >= 0:
                output[stop_row][c] = val
            else:
                output[source_row - 1][c] = val

    return output

